                  </div>
                </>
              ) : (
                <>
                  {/* Celebratory state with session stats */}
                  {reviewedCount > 0 && (
                    <div className="text-center mb-3">
                      <Text className="text-4xl">🎉</Text>
                      <div className="mt-2">
                        <Text strong className="text-lg">
                          {isCramMode
                            ? t("option:flashcards.reviewedThisCramSession", {
