                        })}
                  </Text>

                  {/* Next due date information */}
                  {!isCramMode && nextDueInfo && (
                    <div className="mt-4 p-3 rounded-lg bg-surface2 border border-border">
                      {nextDueInfo.nextDueAt ? (
                        <>
                          <div className="flex items-center gap-2 text-sm">
                            <Calendar className="size-4 text-primary" aria-hidden="true" />
                            <Text strong>
                              {t("option:flashcards.nextDueAt", {
                                defaultValue: "Next review: {{time}}",
                                time: nextDueRelativeLabel ?? nextDueInfo.nextDueAt
                              })}
                            </Text>
                          </div>
                          <Text type="secondary" className="text-xs mt-1 block">
                            {nextDueAbsoluteLabel ?? nextDueInfo.nextDueAt}
                            {" · "}
                            {t("option:flashcards.nextDueHourCount", {
                              defaultValue: "{{count}} cards due within the following hour",
                              count: nextDueInfo.cardsDue
                            })}
                          </Text>
                        </>
                      ) : (
                        <Text strong className="text-sm">
                          {t("option:flashcards.nextDueUnavailable", {
                            defaultValue: "Next review estimate unavailable"
                          })}
                        </Text>
                      )}
                      {nextDueInfo.isCapped && (
                        <Text type="secondary" className="text-xs mt-2 block">
                          {t("option:flashcards.nextDueScanLimited", {
                            defaultValue:
                              "Estimate based on the first {{count}} cards. The count may be incomplete. Narrow filters to improve the estimate.",
                            count: nextDueInfo.scanned
                          })}
                        </Text>
                      )}
                    </div>
                  )}

                  {renderUndoRatingAction()}
                  <Space wrap>
                    {hasCramPracticeCards && (
                      <Button
                        type="primary"
                        onClick={() => {
                          setReviewMode("cram")
                          setPracticedCramCardIds(new Set())
                          setReviewedCount(0)
                          setSelectedStudySessionId(null)
                        }}
                        data-testid="flashcards-review-practice-again"
                      >
                        {t("option:flashcards.practiceAgain", {
                          defaultValue: "Practice again"
                        })}
                      </Button>
                    )}
                    <Button onClick={onNavigateToCreate}>
                      {t("option:flashcards.createMoreCards", {
                        defaultValue: "Create card"
                      })}
                    </Button>
                    {reviewDeckId != null && onNavigateToManageDeck && (
                      <Button
                        onClick={() => onNavigateToManageDeck(reviewDeckId)}
                        data-testid="flashcards-review-manage-deck"
                      >
                        {t("option:flashcards.manageDeckCards", {
                          defaultValue: "Manage deck/cards"
                        })}
                      </Button>
                    )}
                    {reviewDeckId != null && (
                      <Button
                        onClick={() => {
                          const schedulerParams = new URLSearchParams({
                            tab: "scheduler",
                            deck_id: String(reviewDeckId)
                          })
                          if (forceShowWorkspaceItems) {
                            schedulerParams.set("include_workspace_items", "1")
                          }
                          navigate(`/flashcards?${schedulerParams.toString()}`)
                        }}
                        data-testid="flashcards-review-open-scheduler"
                      >
                        {t("option:flashcards.openScheduler", {
                          defaultValue: "Open scheduler"
                        })}
                      </Button>
                    )}
                  </Space>
                  {activeReviewSessionId != null && (
                    <Button
                      type="default"
                      loading={reviewRun.isPending}
                      onClick={() => {
                        void completeReviewSession("manual")
                      }}
                      data-testid="flashcards-review-end-session-empty"
                    >
                      {t("option:flashcards.endSession", {
                        defaultValue: "End Session"
                      })}
                    </Button>
                  )}
                </>
              )}
          </Space>
        </Empty>
      </Card>
      )}
      {selectedStudySessionId != null && (
        <div className="mt-4">
          <StudySuggestionsPanel
            anchorType="flashcard_review_session"
            anchorId={selectedStudySessionId}
            onActionResult={handleStudySuggestionActionResult}
          />
        </div>
      )}
      <div className="mt-4">
        <RecentStudySessions
          deckId={reviewDeckId ?? null}
          decks={availableDecks}
          selectedSessionId={selectedStudySessionId}
          onOpenSession={(sessionId) => {
            setSelectedStudySessionId(sessionId)
          }}
          isActive={isActive}
        />
      </div>
      <FlashcardEditDrawer
        open={editDrawerOpen}
        onClose={() => setEditDrawerOpen(false)}
        card={activeCard ?? null}
        onSave={handleSaveEdit}
        onDelete={handleDeleteFromReview}
        onResetScheduling={handleResetSchedulingFromReview}
        isLoading={
          updateMutation.isPending ||
          deleteMutation.isPending ||
          resetSchedulingMutation.isPending
        }
        decks={decksQuery.data || []}
        decksLoading={decksQuery.isLoading}
      />
    </div>
  )
}

