                          {hasActiveFilters ? (
                            <Button onClick={clearAllFilters}>
                              {t("option:flashcards.clearFilters", {
                                defaultValue: "Clear filters"
                              })}
                            </Button>
                          ) : (
                            <>
                              <Button
                                type="primary"
                                onClick={openManualCreateDrawer}
                                data-testid="flashcards-manage-empty-create-cta"
                              >
                                {t("option:flashcards.noCardsCreateCta", {
                                  defaultValue: "Create card"
                                })}
                              </Button>
                              <Button
                                onClick={onNavigateToImport}
                                data-testid="flashcards-manage-empty-import-cta"
                              >
                                {t("option:flashcards.noCardsImportCta", {
                                  defaultValue: "Import flashcards"
                                })}
                              </Button>
                              <Button
                                onClick={onNavigateToGenerate ?? onNavigateToImport}
                                data-testid="flashcards-manage-empty-generate-cta"
                              >
                                {t("option:flashcards.noCardsGenerateCta", {
                                  defaultValue: "Generate from text"
                                })}
                              </Button>
                            </>
                          )}
                        </Space>
                      </Space>
                    </Empty>
                  )
                )}
              </div>
            </Spin>
          )
        ) : (
          <div>
            {pendingDeletionItems.length > 0 ? (
              <ul
                aria-label={t("option:flashcards.trash", { defaultValue: "Trash" })}
                className="m-0 list-none divide-y divide-border p-0"
              >
                {pendingDeletionItems.map((item) => {
                  const remainingSeconds = Math.max(0, Math.ceil((item.expiresAt - nowMs) / 1000))
                  return (
                    <li
                      key={`flashcard-trash-${item.card.uuid}`}
                      className="flex flex-wrap items-start gap-3 py-3"
                      data-testid={`flashcard-trash-${item.card.uuid}`}
                    >
                      <div className="min-w-0 flex-1">
                        <div className="min-w-0">
                          <div>
                            <Text>{item.card.front}</Text>
                          </div>
                          <div className="mt-1">
                            {item.card.back ? (
                              <Text type="secondary" className="text-xs">
                                {item.card.back.slice(0, 120)}
                                {item.card.back.length > 120 ? "…" : ""}
                              </Text>
                            ) : null}
                          </div>
                        </div>
                      </div>
                      <div className="flex shrink-0 items-center gap-2">
                        <Button
                          key="undo"
                          className="min-h-11 min-w-11"
                          onClick={() => undoSinglePendingDeletion(item.card.uuid)}
                        >
                          {t("option:flashcards.trashUndo", { defaultValue: "Undo" })}
                        </Button>
                        <Tag
                          key="expires"
                          color="volcano"
                          role="timer"
                          aria-live={remainingSeconds <= 10 ? "assertive" : "off"}
                          aria-label={t("option:flashcards.trashExpiresInAria", {
                            defaultValue: "Permanently deletes in {{seconds}} seconds",
                            seconds: remainingSeconds
                          })}
                        >
                          {t("option:flashcards.trashExpiresIn", {
                            defaultValue: "Deletes in {{seconds}}s",
                            seconds: remainingSeconds
                          })}
                        </Tag>
                      </div>
                    </li>
                  )
                })}
              </ul>
            ) : (
              <Empty
                description={t("option:flashcards.trashEmptyDescription", {
                  defaultValue: "Deleted cards appear here for 30 seconds."
                })}
              />
            )}
          </div>
        )}

        {viewMode === "cards" && !isDocumentMode && (
        <div className="mt-3 flex justify-end">
          <Pagination
            current={page}
            pageSize={pageSize}
            onChange={(p, ps) => {
              setPage(p)
              setPageSize(ps)
            }}
            total={totalCount}
            showSizeChanger
            pageSizeOptions={[10, 20, 50, 100]}
          />
        </div>
        )}
      </div>

      {/* Floating Action Bar - appears when items are selected */}
      {viewMode === "cards" && anySelection && (
        <div className="fixed bottom-4 left-1/2 -translate-x-1/2 z-50 bg-surface border border-border rounded-lg shadow-lg px-4 py-3 flex items-center gap-4">
          <Badge
            count=<span className="flex items-center gap-1">
                {/* Icon indicator for colorblind differentiation */}
                {selectAllAcross ? (
                  <CheckCheck className="size-3" aria-hidden="true" />
                ) : (
                  <Check className="size-3" aria-hidden="true" />
                )}
                {selectedCount}
              </span>
            showZero={false}
            style={{ backgroundColor: selectAllAcross ? "rgb(var(--color-primary))" : "rgb(var(--color-success))" }}
          />
          <span className="text-sm text-text-muted">
            {selectedIdsMaySpanPages
              ? t("option:flashcards.selectedFailedForRetry", {
                  defaultValue: "failed cards selected for retry"
                })
              : selectAllAcross
                ? t("option:flashcards.selectedAcrossAll", {
                    defaultValue: "selected across all results"
                  })
                : t("option:flashcards.selected", { defaultValue: "selected" })}
          </span>
          <div className="h-4 w-px bg-border" />
          <Space>
            <Button size="small" onClick={openBulkMove}>
              {t("option:flashcards.bulkMove", { defaultValue: "Move" })}
            </Button>
            <Button size="small" onClick={() => openBulkTagEditor("add")}>
              {t("option:flashcards.bulkAddTag", { defaultValue: "Add tag" })}
            </Button>
            <Button size="small" onClick={() => openBulkTagEditor("remove")}>
              {t("option:flashcards.bulkRemoveTag", { defaultValue: "Remove tag" })}
            </Button>
            <Button size="small" onClick={handleExportSelected}>
              {t("option:flashcards.export", { defaultValue: "Export" })}
            </Button>
            <Button size="small" danger onClick={handleBulkDelete}>
              {t("option:flashcards.bulkDelete", { defaultValue: "Delete" })}
            </Button>
          </Space>
          <div className="h-4 w-px bg-border" />
          <Button type="text" size="small" onClick={clearSelection}>
            {t("option:flashcards.clear", { defaultValue: "Clear" })}
          </Button>
        </div>
      )}

      <Modal
        open={bulkTagOpen}
        destroyOnHidden
        title={
          bulkTagMode === "add"
            ? t("option:flashcards.bulkAddTagTitle", {
                defaultValue: "Add tags to selected cards"
              })
            : t("option:flashcards.bulkRemoveTagTitle", {
                defaultValue: "Remove tags from selected cards"
              })
        }
        onCancel={() => {
          setBulkTagOpen(false)
          setBulkTagInput("")
        }}
        onOk={submitBulkTagEdit}
        okText={
          bulkTagMode === "add"
            ? t("option:flashcards.bulkAddTag", { defaultValue: "Add tag" })
            : t("option:flashcards.bulkRemoveTag", { defaultValue: "Remove tag" })
        }
      >
        <Space orientation="vertical" className="w-full">
          <Text type="secondary">
            {t("option:flashcards.bulkTagDescription", {
              defaultValue:
                "Enter one or more tags separated by commas or spaces."
            })}
          </Text>
          <Input
            value={bulkTagInput}
            onChange={(event) => setBulkTagInput(event.target.value)}
            onPressEnter={submitBulkTagEdit}
            placeholder={t("option:flashcards.bulkTagPlaceholder", {
              defaultValue: "example-tag, chapter-1"
            })}
            data-testid="flashcards-bulk-tag-input"
          />
        </Space>
      </Modal>

      <Modal
        open={deckScopeOpen}
        title={t("option:flashcards.deckScopeTitle", {
          defaultValue: "Move deck scope"
        })}
        onCancel={closeDeckScopeEditor}
        onOk={() => {
          void submitDeckScopeEdit()
        }}
        okText={t("common:save", { defaultValue: "Save" })}
        cancelText={t("common:cancel", { defaultValue: "Cancel" })}
        confirmLoading={updateDeckMutation.isPending}
      >
        <Form form={deckScopeForm} layout="vertical">
          <Form.Item
            name="workspaceId"
            label={t("option:flashcards.workspaceId", { defaultValue: "Workspace ID" })}
          >
            <Input
              placeholder={t("option:flashcards.workspaceIdPlaceholder", {
                defaultValue: "Leave blank for general scope"
              })}
            />
          </Form.Item>
          <Form.Item
            name="parentDeckId"
            label={t("option:flashcards.parentDeck", { defaultValue: "Parent deck" })}
          >
            <Select<number>
              allowClear
              placeholder={t("option:flashcards.topLevelDeck", {
                defaultValue: "Top-level deck"
              })}
              options={deckParentOptions}
            />
          </Form.Item>
        </Form>
      </Modal>

      {/* Move Drawer */}
      <Drawer
        title={
          moveCard
            ? t("option:flashcards.moveToDeck", { defaultValue: "Move to deck" })
            : t("option:flashcards.bulkMove", { defaultValue: "Bulk Move" })
        }
        placement="right"
        styles={{ wrapper: { width: FLASHCARDS_DRAWER_WIDTH_PX } }}
        open={moveOpen}
        onClose={() => {
          setMoveOpen(false)
          setMoveCard(null)
          setMoveDeckId(null)
        }}
        footer=<div className="flex justify-end">
            <Space>
              <Button
                onClick={() => {
                  setMoveOpen(false)
                  setMoveCard(null)
                  setMoveDeckId(null)
                }}
              >
                {t("common:cancel", { defaultValue: "Cancel" })}
              </Button>
            <Button
              type="primary"
              onClick={submitMove}
              disabled={!moveCard && moveDeckId == null}
            >
              {t("option:flashcards.move", { defaultValue: "Move" })}
            </Button>
            </Space>
          </div>
      >
        <Select<number>
          className="w-full"
          allowClear
          loading={decksQuery.isLoading}
          value={moveDeckId ?? undefined}
          onChange={(v) => setMoveDeckId(v ?? null)}
          options={(decksQuery.data || []).map((d) => ({
            label: formatDeckHierarchyLabel(d, deckMap, `Deck ${d.id}`),
            value: d.id
          }))}
        />
      </Drawer>

      {/* Edit Drawer */}
      <FlashcardEditDrawer
        open={editOpen}
        onClose={() => {
          setEditOpen(false)
          setEditing(null)
        }}
        card={editing}
        onSave={doUpdate}
        onDelete={doDelete}
        onResetScheduling={doResetScheduling}
        isLoading={updateMutation.isPending || resetSchedulingMutation.isPending}
        decks={decksQuery.data || []}
        decksLoading={decksQuery.isLoading}
      />

      {/* Create Drawer */}
      <FlashcardCreateDrawer
        open={createOpen}
        onClose={closeCreateDrawer}
        decks={decksQuery.data || []}
        decksLoading={decksQuery.isLoading}
        initialDeckId={createDrawerInitialDeckId}
        includeWorkspaceItems={workspaceVisibilityOptions.includeWorkspaceItems}
        workspaceId={workspaceVisibilityOptions.workspaceId}
      />

      {/* Floating Action Button for creating cards */}
      {viewMode === "cards" && !anySelection && (
        <Tooltip title={t("option:flashcards.createCard", { defaultValue: "Create card" })}>
          <Button
            type="primary"
            shape="circle"
            size="large"
            icon=<Plus className="size-5" />
            className="fixed bottom-6 right-6 z-50 shadow-lg !w-14 !h-14 flex items-center justify-center"
            onClick={openManualCreateDrawer}
            data-testid="flashcards-fab-create"
            aria-label={t("option:flashcards.createCard", { defaultValue: "Create card" })}
          />
        </Tooltip>
      )}

      {/* Bulk operation progress modal */}
      <Modal
        open={bulkProgress?.open ?? false}
        closable={false}
        footer={null}
        centered
        title={
          bulkProgress?.action ||
          t("option:flashcards.bulkProgressTitle", { defaultValue: "Processing" })
        }
      >
        <div className="flex flex-col items-center gap-4 py-4">
          <Spin size="large" />
          <div className="text-center">
            <Text className="block text-lg">
              {bulkProgress?.current ?? 0} / {bulkProgress?.total ?? 0}
            </Text>
            <Text type="secondary" className="block mt-1">
              {t("option:flashcards.bulkProgressPleaseWait", {
                defaultValue: "Please wait..."
              })}
            </Text>
          </div>
          <Progress
            percent={Math.round(
              ((bulkProgress?.current ?? 0) / (bulkProgress?.total || 1)) * 100
            )}
            status="active"
            className="w-full max-w-xs"
          />
        </div>
      </Modal>

      {/* Type-to-confirm modal for large bulk deletes */}
      <Modal
        open={bulkDeleteConfirmOpen}
        title={t("option:flashcards.bulkDeleteLargeTitle", {
          defaultValue: "Delete {{count}} cards?",
          count: bulkDeleteCount
        })}
        onCancel={() => {
          setBulkDeleteConfirmOpen(false)
          setBulkDeleteInput("")
          setPendingDeleteItems([])
          setBulkDeleteCount(0)
        }}
        okText={t("common:delete", { defaultValue: "Delete" })}
        cancelText={t("common:cancel", { defaultValue: "Cancel" })}
        okButtonProps={{
          danger: true,
          disabled: bulkDeleteInput.toUpperCase() !== "DELETE"
        }}
        onOk={confirmLargeBulkDelete}
        centered
      >
        <div className="space-y-4">
          <DsAlert
            variant="warning"
            title={t("option:flashcards.bulkDeleteLargeWarning", {
              defaultValue: "These cards will move to Trash for {{seconds}} seconds.",
              seconds: DELETE_UNDO_SECONDS
            })}
          />
          <p className="text-text-muted">
            {t("option:flashcards.bulkDeleteLargeContent", {
              defaultValue:
                "After {{seconds}} seconds, {{count}} cards will be permanently deleted.",
              count: bulkDeleteCount,
              seconds: DELETE_UNDO_SECONDS
            })}
          </p>
          <div className="pt-2">
            <p className="text-sm font-medium text-text-muted mb-2">
              {t("option:flashcards.typeDeleteToConfirm", {
                defaultValue: "Type DELETE to confirm:"
              })}
            </p>
            <Input
              value={bulkDeleteInput}
              onChange={(e) => setBulkDeleteInput(e.target.value)}
              placeholder="DELETE"
              className="font-mono"
              autoFocus
            />
          </div>
        </div>
      </Modal>
    </>
  )
}

export default ManageTab

import React from "react"
import {
  Badge,
  Button,
  Collapse,
  Drawer,
  Form,
  Input,
  Modal,
  Select,
  Space,
  Tooltip,
  Typography
} from "antd"
import type { TextAreaRef } from "antd/es/input/TextArea"
import { useTranslation } from "react-i18next"
import { useAntdMessage } from "@/hooks/useAntdMessage"
import { useDebouncedFormField } from "../hooks"
import { FLASHCARDS_DRAWER_WIDTH_PX } from "../constants"
import { formatFlashcardTimestampWithRelative } from "../utils/date-display"
import { normalizeFlashcardTemplateFields } from "../utils/template-helpers"
import { normalizeOptionalFlashcardTags } from "../utils/tag-normalization"
import {
  FLASHCARD_FIELD_MAX_BYTES,
  getFlashcardFieldLimitState,
  getUtf8ByteLength
} from "../utils/field-byte-limit"
import { getFlashcardSourceMeta } from "../utils/source-reference"
import {
  getSelectionFromElement,
  insertTextAtSelection,
  restoreSelection,
  type TextSelection
} from "../utils/text-selection"
import { formatDeckDisplayName } from "../utils/deck-display"
import { FlashcardImageInsertButton } from "./FlashcardImageInsertButton"
import { FlashcardTagPicker } from "./FlashcardTagPicker"
import { MarkdownWithBoundary } from "./MarkdownWithBoundary"
import type { Flashcard, FlashcardUpdate, Deck } from "@/services/flashcards"

const { Text } = Typography
const CLOZE_PATTERN = /\{\{c\d+::[\s\S]+?\}\}/

type FlashcardModelType = Flashcard["model_type"]
type EditableTextField = "front" | "back" | "extra" | "notes"

interface FlashcardEditDrawerProps {
  open: boolean
  onClose: () => void
  card: Flashcard | null
  onSave: (values: FlashcardUpdate) => Promise<void>
  onDelete: () => void
  onResetScheduling?: () => Promise<void>
  isLoading?: boolean
  decks: Deck[]
  decksLoading?: boolean
}

export const FlashcardEditDrawer: React.FC<FlashcardEditDrawerProps> = ({
  open,
  onClose,
  card,
  onSave,
  onDelete,
  onResetScheduling,
  isLoading = false,
  decks,
  decksLoading = false
}) => {
  const { t } = useTranslation(["option", "common"])
  const message = useAntdMessage()
  const [form] = Form.useForm<FlashcardUpdate & { tags_text?: string[] }>()
  const selectedModelType = Form.useWatch("model_type", form) as
    | FlashcardModelType
    | undefined
  const [showPreview, setShowPreview] = React.useState(false)
  const [isDirty, setIsDirty] = React.useState(false)
  const [confirmCloseOpen, setConfirmCloseOpen] = React.useState(false)
  const [confirmResetOpen, setConfirmResetOpen] = React.useState(false)

  const frontPreview = useDebouncedFormField(form, "front")
  const backPreview = useDebouncedFormField(form, "back")
  const extraPreview = useDebouncedFormField(form, "extra")
  const notesPreview = useDebouncedFormField(form, "notes")
  const frontValue = Form.useWatch("front", form) as string | undefined
  const backValue = Form.useWatch("back", form) as string | undefined
  const textAreaRefs = React.useRef<Record<EditableTextField, TextAreaRef | null>>({
    front: null,
    back: null,
    extra: null,
    notes: null
  })
  const selectionRef = React.useRef<Record<EditableTextField, TextSelection>>({
    front: { start: 0, end: 0 },
    back: { start: 0, end: 0 },
    extra: { start: 0, end: 0 },
    notes: { start: 0, end: 0 }
  })
  const frontByteLength = getUtf8ByteLength(frontValue)
  const backByteLength = getUtf8ByteLength(backValue)
  const frontLimitState = getFlashcardFieldLimitState(frontByteLength)
  const backLimitState = getFlashcardFieldLimitState(backByteLength)

  const previewLabel = t("option:flashcards.preview", { defaultValue: "Preview" })
  const markdownSupportHint = t("option:flashcards.markdownSupportHint", {
    defaultValue: "Supports Markdown and LaTeX."
  })
  const isClozeTemplate = selectedModelType === "cloze"
  const sourceMeta = React.useMemo(
    () => (card ? getFlashcardSourceMeta(card) : null),
    [card]
  )
  const dueAtDisplay = formatFlashcardTimestampWithRelative(card?.due_at)
  const lastReviewedDisplay = formatFlashcardTimestampWithRelative(
    card?.last_reviewed_at
  )

  const templateHelperText = React.useMemo(() => {
    if (selectedModelType === "basic_reverse") {
      return t("option:flashcards.templateReverseHelp", {
        defaultValue:
          "Choose Basic + Reverse when you want both directions (term -> meaning and meaning -> term)."
      })
    }
    if (selectedModelType === "cloze") {
      return t("option:flashcards.templateClozeHelp", {
        defaultValue:
          "Choose Cloze when you want to hide key words inside a sentence or paragraph."
      })
    }
    return t("option:flashcards.templateBasicHelp", {
      defaultValue:
        "Choose Basic for direct question and answer cards (facts, definitions, short prompts)."
    })
  }, [selectedModelType, t])

  const renderByteUsageHint = React.useCallback(
    (field: "front" | "back", byteLength: number, state: "normal" | "warning" | "over") => {
      const fieldLabel = t(`option:flashcards.${field}`, {
        defaultValue: field === "front" ? "Front" : "Back"
      })
      const usageText = t("option:flashcards.fieldByteUsage", {
        defaultValue: "{{field}}: {{used}} / {{max}} bytes",
        field: fieldLabel,
        used: byteLength,
        max: FLASHCARD_FIELD_MAX_BYTES
      })
      if (state === "over") {
        return t("option:flashcards.fieldByteOverLimit", {
          defaultValue: "{{usage}}. Exceeds limit by {{over}} bytes.",
          usage: usageText,
          over: byteLength - FLASHCARD_FIELD_MAX_BYTES
        })
      }
      if (state === "warning") {
        return t("option:flashcards.fieldByteNearLimit", {
          defaultValue: "{{usage}}. Approaching the {{max}}-byte limit.",
          usage: usageText,
          max: FLASHCARD_FIELD_MAX_BYTES
        })
      }
      return usageText
    },
    [t]
  )

  // Count how many additional fields have values for the badge indicator
  const additionalFieldCount = React.useMemo(() => {
    let count = 0
    if (extraPreview && extraPreview.trim()) count++
    if (notesPreview && notesPreview.trim()) count++
    return count
  }, [extraPreview, notesPreview])

  // Sync form with card data when card changes
  React.useEffect(() => {
    if (card && open) {
      form.setFieldsValue({
        deck_id: card.deck_id ?? undefined,
        front: card.front,
        back: card.back,
        notes: card.notes || undefined,
        extra: card.extra || undefined,
        tags: card.tags || undefined,
        model_type: card.model_type,
        expected_version: card.version
      })
      setIsDirty(false)
    }
  }, [card, open, form])

  // Track form changes
  const handleFormChange = React.useCallback(() => {
    setIsDirty(true)
  }, [])

  const syncTemplateFields = React.useCallback(
    (partial: Partial<Pick<FlashcardUpdate, "model_type" | "reverse" | "is_cloze">>) => {
      const normalized = normalizeFlashcardTemplateFields(partial)
      form.setFieldsValue({
        model_type: normalized.model_type,
        reverse: normalized.reverse,
        is_cloze: normalized.is_cloze
      })
    },
    [form]
  )

  const handleSave = async () => {
    try {
      const rawValues = (await form.validateFields()) as FlashcardUpdate
      const values = normalizeFlashcardTemplateFields({
        ...rawValues,
        tags: normalizeOptionalFlashcardTags(rawValues.tags)
      })
      await onSave(values)
    } catch (e: any) {
      // Validation errors handled by form
      if (!e?.errorFields) {
        console.error("Save error:", e)
      }
    }
  }

  const handleClose = React.useCallback(() => {
    form.resetFields()
    setIsDirty(false)
    setConfirmCloseOpen(false)
    setConfirmResetOpen(false)
    onClose()
  }, [form, onClose])

  const handleAttemptClose = React.useCallback(() => {
    if (isDirty) {
      setConfirmCloseOpen(true)
    } else {
      handleClose()
    }
  }, [handleClose, isDirty])

  const handleConfirmResetScheduling = React.useCallback(async () => {
    if (!onResetScheduling) return
    try {
      await onResetScheduling()
      setConfirmResetOpen(false)
      setIsDirty(false)
    } catch (e: unknown) {
      console.error("Reset scheduling error:", e)
    }
  }, [onResetScheduling])

  const updateSelection = React.useCallback(
    (
      field: EditableTextField,
      element: HTMLTextAreaElement | null | undefined
    ) => {
      const currentValue = String(form.getFieldValue(field) ?? "")
      selectionRef.current[field] = getSelectionFromElement(element, currentValue)
    },
    [form]
  )

  const handleInsertImage = React.useCallback(
    async (field: EditableTextField, markdownSnippet: string) => {
      const currentValue = String(form.getFieldValue(field) ?? "")
      const textArea =
        textAreaRefs.current[field]?.resizableTextArea?.textArea ?? null
      const selection =
        selectionRef.current[field] ?? getSelectionFromElement(textArea, currentValue)
      const { nextValue, cursor } = insertTextAtSelection(
        currentValue,
        selection,
        markdownSnippet
      )
      form.setFieldsValue({ [field]: nextValue })
      setIsDirty(true)
      restoreSelection(textArea, cursor)
    },
    [form]
  )

  const renderFieldLabel = React.useCallback(
    (field: EditableTextField, label: string) => (
      <div className="flex items-center justify-between gap-3">
        <span>{label}</span>
        <FlashcardImageInsertButton
          ariaLabel={`Upload image for ${label}`}
          buttonLabel={t("option:flashcards.insertImage", {
            defaultValue: "Insert image"
          })}
          onInsert={(markdownSnippet) => handleInsertImage(field, markdownSnippet)}
          onError={(error) => message.error(error.message)}
        />
      </div>
    ),
    [handleInsertImage, message, t]
  )

  return (
    <>
    <Drawer
      placement="right"
      styles={{ wrapper: { width: FLASHCARDS_DRAWER_WIDTH_PX } }}
      open={open}
      onClose={handleAttemptClose}
      title={t("option:flashcards.editCard", { defaultValue: "Edit Flashcard" })}
      footer={
        <div className="flex justify-end">
          <Space>
            <Button onClick={handleAttemptClose}>
              {t("common:cancel", { defaultValue: "Cancel" })}
            </Button>
            <Button danger onClick={onDelete}>
              {t("common:delete", { defaultValue: "Delete" })}
            </Button>
            <Button type="primary" loading={isLoading} onClick={handleSave}>
              {t("common:save", { defaultValue: "Save" })}
            </Button>
          </Space>
        </div>
      }
    >
      <Form form={form} layout="vertical" onValuesChange={handleFormChange}>
        {/* Section: Organization */}
        <div className="mb-6">
          <h3 className="text-sm font-medium text-text-muted mb-3">
